interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

async function getPost(id: string): Promise<Post | null> {
  const post = (await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}`
  ).then((res) => res.json())) as Post | Record<string, never>

  return 'id' in post ? post : null
}

async function getComments(id: string): Promise<Comment[]> {
  return fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`).then(
    (res) => res.json()
  )
}

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    return { title: 'Post Not Found - My Blog' }
  }

  return {
    title: `${post.title} - My Blog`,
    description: post.body.substring(0, 160),
    openGraph: {
      title: post.title,
      description: post.body.substring(0, 160),
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params

  let post: Post | null
  let comments: Comment[]

  try {
    ;[post, comments] = await Promise.all([getPost(id), getComments(id)])
  } catch {
    notFound()
  }

  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

