}

import { NextResponse } from 'next/server'

interface Post {
  id: number
  title: string
  content: string
}

interface FetchedPost extends Post {
  createdAt: string
}

interface UpdatedPost extends Post {
  updatedAt: string
}

interface DeleteResponse {
  message: string
}

interface RouteContext {
  params: Promise<{ id: string }>
}

interface UpdatePostBody {
  title?: string
  content?: string
}

export async function GET(
  _request: Request,
  { params }: RouteContext
): Promise<NextResponse<FetchedPost>> {
  const { id } = await params

  // Simulate fetching a single post
  const post: FetchedPost = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(
  request: Request,
  { params }: RouteContext
): Promise<NextResponse<UpdatedPost>> {
  const { id } = await params
  const { title, content }: UpdatePostBody = await request.json()

  // Simulate updating a post
  const updatedPost: UpdatedPost = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost, { status: 200 })
}

export async function DELETE(
  _request: Request,
  { params }: RouteContext
): Promise<NextResponse<DeleteResponse>> {
  const { id } = await params

  // Simulate deleting a post
  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}
